    (ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  AScheduler LB m S Sv -> as_RHEAP H s LB m ->
  stk bsegs m lo (bv_unsigned sp) -> lo + ASHUT_STACK <= bv_unsigned sp -> aceil <= lo -> mem_inv bsegs m ->
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat -> stack0 m lo shi ->
  (forall (m2 : mem) (spa : Z) (gap : list cell) (p0 p8 p16 p24 pL h32 j88 shb : list byte) (ff fp : Z)
          (rax a0' a1' a2' a3' a4' a5' a6' a7' t0' t1' t2' t3' t4' t5' t6' xs2 xs5 xs8 xs10 xs11 : word),
     rw_cells bsegs m2 spa [CB 8 p0; CB 8 p8; CB 8 p16; CB 8 p24; C8 (Z_to_bv 64 ff); CB 16 pL] ->
     rw_cells bsegs m2 (spa + 56) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 56) ->
     (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176) ->
     rw_cells bsegs m2 (bv_unsigned sp + -104) (sc_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
     rw_cells bsegs m2 ff [CB 32 h32; CB 88 j88; C8 (Z_to_bv 64 fp)] -> rw_cells bsegs m2 (Z.shiftr ff 3 + 2147450880) [CB 16 shb] -> rw_cells bsegs m2 fp [C1 (b8 1)] ->
     stk bsegs m2 lo spa -> mem_inv bsegs m2 ->
     as_RFS H ((1, ff, fp) :: LF) m2 -> fresh_frame H LF 1 ff fp -> ACONST m2 -> stack0 m2 lo shi ->
     munch ([(lo, bv_unsigned sp)]%Z ++ fr1_XS H ff fp) m m2 -> wmono bsegs m m2 ->
     AScheduler LB m2 S Sv -> as_RHEAP H s LB m2 ->
     evt bsegs Q
       (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
                xs2 (Z_to_bv 64 S) (Z_to_bv 64 ff) xs5 (Z_to_bv 64 2147450880) (Z_to_bv 64 ff) xs8 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) xs10 xs11 t3' t4' t5' t6')
           F (Z_to_bv 64 P_A_SHUT_MID) fc None m2 (seg_rom bsegs))) ->
  evt bsegs Q
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz S) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SCHED_SHUTDOWN) fc None m (seg_rom bsegs)).
